import sys

def count_valid_positions(n: int, m: int, p: int, a: List[int], b: List[int]) -> None:
    # Create a frequency dictionary for sequence b
    freq_b = {}
    for num in b:
        if num in freq_b:
            freq_b[num] += 1
        else:
            freq_b[num] = 1

    valid_positions = []

    # Iterate over possible starting points for sequence a
    for q in range(1, n - m * p + 2):
        # Create a frequency dictionary for the current subsequence of a
        freq_a = {}
        for i in range(q - 1, q - 1 + m * p):
            num = a[i]
            if num in freq_a:
                freq_a[num] += 1
            else:
                freq_a[num] = 1

        # Check if the frequencies match
        if freq_a == freq_b:
            valid_positions.append(q)

