def find_valid_positions(n, m, p, a, b):
    target_counts = {}
    for num in b:
        if num in target_counts:
            target_counts[num] += 1
        else:
            target_counts[num] = 1

    valid_positions = []
    current_window_counts = {}

    def is_valid():
        for key in target_counts:
            if target_counts[key] != current_window_counts.get(key, 0):
                return False
        return True

    for i in range(m - 1):
        if a[i] in current_window_counts:
            current_window_counts[a[i]] += 1
        else:
            current_window_counts[a[i]] = 1

    for i in range(m - 1, n):
        if a[i] in current_window_counts:
            current_window_counts[a[i]] += 1
        else:
            current_window_counts[a[i]] = 1

        if is_valid():
            valid_positions.append((i - m + 1) // p)

        remove_index = i - m + 1
        if current_window_counts[a[remove_index]] > 1:
            current_window_counts[a[remove_index]] -= 1
        else:
            del current_window_counts[a[remove_index]]

    return len(valid_positions), valid_positions

